void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;

    // 1. Current Frame (Sharp)
    vec3 current = texture(iChannel0, uv).rgb;

    // 2. Blur Logic
    // We sample the current texture multiple times to create bloom
    vec3 blur = vec3(0.0);
    vec2 pixel = 1.0 / iResolution.xy;

    // Simple 5-tap gaussian-ish bloom
    blur += texture(iChannel0, uv).rgb * 0.4;
    blur += texture(iChannel0, uv + vec2(2.0*pixel.x, 0.0)).rgb * 0.15;
    blur += texture(iChannel0, uv - vec2(2.0*pixel.x, 0.0)).rgb * 0.15;
    blur += texture(iChannel0, uv + vec2(0.0, 2.0*pixel.y)).rgb * 0.15;
    blur += texture(iChannel0, uv - vec2(0.0, 2.0*pixel.y)).rgb * 0.15;

    // 3. Feedback / Trails
    // If we wanted true trails we would need Buffer B, 
    // but here we just composite the blur heavily for the "dreamy" look.

    vec3 final = current + blur * 0.8;

    // Tone mapping
    final = final / (final + vec3(1.0));
    final = pow(final, vec3(0.4545));

    fragColor = vec4(final, 1.0);
}

// --- Common: Shared Data ---
#define PI 3.14159

// --- SDF Functions from Shader 1 ---
float sdBox( in vec2 p, in vec2 b ) {
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}

float sdCapsule( vec2 p, vec2 a, vec2 b, float r ) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return length( pa - ba*h ) - r;
}

float sdSegment( in vec2 p, in vec2 a, in vec2 b ) {
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return length( pa - ba*h );
}

// --- Random Generators ---
float hash11(float p) {
    p = fract(p * .1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

vec3 hash31(float p) {
   vec3 p3 = fract(vec3(p) * vec3(.1031, .1030, .0973));
   p3 += dot(p3, p3.yzx+33.33);
   return fract((p3.xxy+p3.yzz)*p3.zyx);
}

vec3 getLightColor(float id) {
    float i = mod(id, 4.0);
    if(i < 0.5) return vec3(1.0, 0.1, 0.1); // Red
    if(i < 1.5) return vec3(0.1, 1.0, 0.2); // Green
    if(i < 2.5) return vec3(0.2, 0.5, 1.0); // Blue
    return vec3(1.0, 0.8, 0.1);             // Gold
}

#define SPEED 3.0
#define CHUNK_LEN 25.0
#define TUNNEL_RAD 5.0
#define STRINGS 6 
#define LIGHTS_PER_STRING 8.0 

// --- Helper Functions ---

// Draw the detailed bulb shape
vec3 drawBulb(vec2 p, vec3 color, float scale, float blink, float distToCam) {
    vec3 col = vec3(0.0);
    p /= scale; // Normalize coordinates for SDFs

    // 1. Socket (Green box)
    float socketDist = sdBox(p - vec2(0.0, -0.02), vec2(0.02, 0.025));
    float socketMask = smoothstep(0.005/scale * distToCam, 0.0, socketDist);
    col = mix(col, vec3(0.05, 0.15, 0.05), socketMask);

    // 2. Bulb (Glass Capsule)
    float bulbDist = sdCapsule(p, vec2(0.0, -0.05), vec2(0.0, -0.12), 0.035);
    float bulbMask = smoothstep(0.005/scale * distToCam, 0.0, bulbDist);

    // 3. Light State
    float intensity = smoothstep(0.1, 0.3, blink);
    vec3 litColor = color * 2.5; // Brightness boost
    vec3 unlitColor = color * 0.1 + vec3(0.1);
    vec3 finalBulbCol = mix(unlitColor, litColor, intensity);

    col = mix(col, finalBulbCol, bulbMask);

    // 4. Glow (SDF based bloom)
    if (intensity > 0.01) {
        float d = length(p - vec2(0.0, -0.1));
        // Inverse square falloff for realistic light
        float glow = 0.005 / (d * d);
        glow = min(glow, 1.0);
        col += color * glow * intensity * 0.6;
    }

    // 5. Specular Highlight (Shiny glass)
    float highlight = smoothstep(0.01, 0.0, length(p - vec2(0.015, -0.08)) - 0.005);
    col = mix(col, vec3(1.0), highlight * 0.5);

    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 col = vec3(0.0); // Start with black

    float camZ = iTime * SPEED;
    // Camera movement: Forward + slight sway
    vec3 ro = vec3(sin(iTime*0.5), cos(iTime*0.3)*0.5, camZ);

    float currentChunk = floor(camZ / CHUNK_LEN);

    // Render Current Chunk + Next Chunk (Infinite loop logic)
    for(int c = 0; c < 2; c++) {
        float chunkID = currentChunk + float(c);
        float chunkZ = chunkID * CHUNK_LEN;

        for(int s = 0; s < STRINGS; s++) {
            float seed = chunkID * 50.0 + float(s);

            // Random start/end points
            vec3 offA = hash31(seed) * 2.0 - 1.0;
            vec3 offB = hash31(seed + 71.2) * 2.0 - 1.0;

            vec3 pA = vec3(offA.xy * TUNNEL_RAD, chunkZ + (offA.z + 1.0) * (CHUNK_LEN*0.25));
            vec3 pB = vec3(offB.xy * TUNNEL_RAD, chunkZ + CHUNK_LEN + (offB.z - 1.0) * (CHUNK_LEN*0.25));

            vec2 prevScreenPos = vec2(100.0); 
            bool prevVisible = false;

            for(float i = 0.0; i <= LIGHTS_PER_STRING; i++) {
                float t = i / LIGHTS_PER_STRING;

                // String Physics (Sag + Sway)
                float sag = sin(t * PI) * 1.5; 
                vec3 worldPos = mix(pA, pB, t);
                worldPos.y -= sag;

                float sway = sin(iTime * 2.0 + worldPos.x + worldPos.z)*0.2;
                worldPos.x += sway; 

                // Local Camera Space
                vec3 pLocal = worldPos - ro;

                // Clipping Plane (Don't draw behind camera or too far)
                if(pLocal.z > 0.1 && pLocal.z < CHUNK_LEN) {
                    vec2 screenPos = pLocal.xy / pLocal.z;

                    // --- Fog Factor ---
                    // Calculate fog based on DISTANCE from camera, not global time
                    float fogFactor = 1.0 - smoothstep(CHUNK_LEN * 0.5, CHUNK_LEN, pLocal.z);

                    // --- Draw Wire ---
                    if (prevVisible) {
                         float dWire = sdSegment(uv, prevScreenPos, screenPos);
                         float thickness = 0.005 / pLocal.z; 
                         float wireAlpha = smoothstep(thickness, 0.0, dWire);
                         // Apply fog to wire
                         col = mix(col, vec3(0.02, 0.05, 0.02) * fogFactor, wireAlpha);
                    }

                    // --- Draw Bulb ---
                    vec2 pToBulb = uv - screenPos;

                    // Rotate bulb slightly
                    float bulbSway = sin(iTime * 3.0 + worldPos.z) * 0.2;
                    float co = cos(bulbSway), si = sin(bulbSway);
                    pToBulb = mat2(co, -si, si, co) * pToBulb;

                    float size = 1.0 / pLocal.z; 

                    // Optimization: Check bounding box before SDF
                    if(length(pToBulb) < 0.25 * size) {
                         vec3 lColor = getLightColor(seed + i);
                         float blink = 0.5 + 0.5 * sin(iTime * 4.0 + (seed+i)*13.0);

                         vec3 bulbCol = drawBulb(pToBulb, lColor, size, blink, pLocal.z);

                         // Apply Fog to Bulb Color
                         bulbCol *= fogFactor;

                         float alpha = smoothstep(0.0, 0.1, length(bulbCol));
                         col = mix(col, bulbCol, alpha);

                         // Additive glow (also faded by fog)
                         col += bulbCol * 0.5 * fogFactor;
                    }

                    prevScreenPos = screenPos;
                    prevVisible = true;
                } else {
                    prevVisible = false;
                }
            }
        }
    }

    fragColor = vec4(col, 1.0);
}
